// and can't drift. A changeset is required only when *publishable* source of a
// versioned package changed — tests, fixtures, docs and markdown stay silent.
//
// Bypass (docs/release-engineering.md): SKIP_CHANGESET_CHECK=1 git push
import {
  changesetRequired,
  hasManualChangeset,
  listChangedFiles,
} from "./changeset-rules.mjs";

const root = process.cwd();
const base = process.env.CHANGED_BASE || process.argv[2] || "origin/main";

const files = listChangedFiles(base, root);
if (files === null) process.exit(0); // no shared base yet (e.g. fresh branch) — skip
if (!changesetRequired(files)) process.exit(0);
if (hasManualChangeset(root)) process.exit(0);

