console.error("  Draft one:  npm run changeset:suggest    (prints a starting point)");
console.error("  Add one:    npx changeset add\n");
console.error("No release intended? Add an empty changeset (npx changeset add --empty)");
console.error("only after an explicit no-release classification, or bypass with:");
console.error("  SKIP_CHANGESET_CHECK=1 git push");
process.exit(1);

