// Shared predicate for "does this change require a changeset?".
//
// Single source of truth so the two gates can't drift:
//   - hooks/pre-push           -> scripts/require-changeset.mjs (blocks the push)
//   - .github/workflows/ci.yml -> scripts/require-changeset.mjs (fails the PR)
// and reused by scripts/suggest-changeset.mjs to draft one.
import { existsSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

// Profile manifest packages get auto-derived changesets from
// scripts/add-aggregate-changesets.mjs when a bundled member changes, so a
// profile-only edit needs no manual changeset.
export const PROFILE_DIRS = ["my-pi-actions", "my-pi-full", "my-pi-harness", "my-pi-pod"];

// A changed file is release-impacting when it is source of a versioned package...
export const VERSIONED_SOURCE = /^(?:extensions|packages|services)\/[^/]+\//;

// ...but NOT when it is only a test, fixture, doc or markdown file. Changing only
// these ships no release, so they must not trip the gate (otherwise every test /
// docs PR is forced to add an empty changeset just to stay green).
export const NON_PUBLISHABLE =
  /(?:^|\/)(?:__tests__|__fixtures__|tests?|fixtures|docs)\/|(?:\.(?:test|spec)\.[cm]?[jt]sx?|\.snap|\.mdx?)$/i;

const AUTO_CHANGESET_SOURCE = new RegExp(`^packages/(?:${PROFILE_DIRS.join("|")})/`);

/** Does this single changed path, on its own, require a manual changeset? */
export function pathNeedsChangeset(file) {
  return (
    VERSIONED_SOURCE.test(file) &&
    !AUTO_CHANGESET_SOURCE.test(file) &&
    !NON_PUBLISHABLE.test(file)
  );
}

/** Does this set of changed files require a manual changeset? */
export function changesetRequired(files) {
  return files.some(pathNeedsChangeset);
}

/** Changed files vs `base` (three-dot), or null when there is no shared base. */
export function listChangedFiles(base, cwd = process.cwd()) {
  const diff = spawnSync("git", ["diff", "--name-only", `${base}...HEAD`], {
    cwd,
    encoding: "utf8",
  });
  if (diff.status !== 0) return null;
  return diff.stdout.split("\n").filter(Boolean);
}

/** Is there at least one author-written changeset in .changeset/? */
export function hasManualChangeset(cwd = process.cwd()) {
  const dir = join(cwd, ".changeset");
  const generated = new Set(["README.md", "aggregate-profiles.md"]);
  return (
    existsSync(dir) &&
    readdirSync(dir).some((f) => f.endsWith(".md") && !generated.has(f))
  );
}

